    public static function obtener(string $clave): array
    {
        $fila = self::todos()[$clave] ?? self::todos()['Default'];
        return array_combine(['nombre', 'campos', 'unidad', 'tipo', 'definicion', 'limite', 'accion'], $fila);
    }
